import { mkdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";

// ESPN's public competition schedule is used only as a structured participant
// source. The generated file contains names, source URL and edition — never a
// guessed club or an unlicensed crest asset.
const edition = "2026.1";
const capturedAt = "2026-09-10";
const root = resolve(import.meta.dirname, "..");
const output = resolve(root, "game/data/club-snapshots.ts");

const competitions = [
  ["bra-a", "Brasil", "bra.1", "calendar"], ["bra-b", "Brasil", "bra.2", "calendar"],
  ["arg-lp", "Argentina", "arg.1", "calendar"], ["arg-pn", "Argentina", "arg.2", "calendar"],
  ["chi-a", "Chile", "chi.1", "calendar"], ["col-a", "Colômbia", "col.1", "calendar"],
  ["uru-a", "Uruguai", "uru.1", "calendar"], ["par-a", "Paraguai", "par.1", "calendar"],
  ["per-a", "Peru", "per.1", "calendar"], ["bol-a", "Bolívia", "bol.1", "calendar"],
  ["ecu-a", "Equador", "ecu.1", "calendar"], ["ven-a", "Venezuela", "ven.1", "calendar"],
  ["eng-pl", "Inglaterra", "eng.1", "european"], ["eng-c", "Inglaterra", "eng.2", "european"],
  ["eng-l1", "Inglaterra", "eng.3", "european"], ["eng-l2", "Inglaterra", "eng.4", "european"],
  ["esp-ll", "Espanha", "esp.1", "european"], ["ita-sa", "Itália", "ita.1", "european"],
  ["ger-bl", "Alemanha", "ger.1", "european"], ["fra-l1", "França", "fra.1", "european"],
  ["por-pl", "Portugal", "por.1", "european"], ["ned-a", "Holanda", "ned.1", "european"],
  ["bel-a", "Bélgica", "bel.1", "european"], ["tur-a", "Turquia", "tur.1", "european"],
  ["gre-a", "Grécia", "gre.1", "european"], ["aut-a", "Áustria", "aut.1", "european"],
  ["den-a", "Dinamarca", "den.1", "european"], ["nor-a", "Noruega", "nor.1", "calendar"],
  ["sco-a", "Escócia", "sco.1", "european"], ["mex-liga", "México", "mex.1", "calendar"],
  ["usa-mls", "Estados Unidos", "usa.1", "calendar"], ["jpn-j1", "Japão", "jpn.1", "calendar"],
  ["aus-al", "Austrália", "aus.1", "european"],
];

function datesFor(calendar) {
  return calendar === "european" ? "20260801-20270531" : "20260101-20261231";
}

async function fetchParticipants([competitionId, country, espnId, calendar]) {
  const url = `https://site.api.espn.com/apis/site/v2/sports/soccer/${espnId}/scoreboard?dates=${datesFor(calendar)}&limit=1000`;
  const response = await fetch(url, { headers: { "user-agent": "O-REI-catalog-sync/1.0" } });
  if (!response.ok) throw new Error(`${competitionId}: HTTP ${response.status}`);
  const payload = await response.json();
  const clubs = [...new Set((payload.events ?? []).flatMap((event) => event.competitions?.[0]?.competitors?.map((competitor) => competitor.team.displayName) ?? []))].sort((a, b) => a.localeCompare(b, "pt-BR"));
  if (!clubs.length) throw new Error(`${competitionId}: a fonte não retornou participantes`);
  return { competitionId, country, clubs, source: url };
}

const settled = await Promise.allSettled(competitions.map(fetchParticipants));
const failures = settled.filter((result) => result.status === "rejected");
if (failures.length) {
  console.error(failures.map((failure) => failure.reason.message).join("\n"));
  process.exit(1);
}

const snapshots = settled.map((result) => result.value);
const body = `// Generated by scripts/sync-club-snapshots.mjs. Do not hand-edit.\n// Edition ${edition}; captured ${capturedAt}.\nexport const clubSnapshots = ${JSON.stringify(snapshots, null, 2)} as const;\n`;
await mkdir(dirname(output), { recursive: true });
await writeFile(output, body, "utf8");
console.log(`Saved ${snapshots.reduce((total, item) => total + item.clubs.length, 0)} club entries across ${snapshots.length} competitions.`);
